import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, Camara, Textura, Profundidad, Brillo, Paso, seguir, enCamino, Chip, Regla, Contador, Ondas, Destello, golpe, sacudida, h, clamp, interpolate, Easing} from './kit';

export const SUBS = {arriba: 230, acento: '#E7FF00'};

// ---- tiempos atados a la voz ----
const ANOS = en('años'), ESPERO1 = en('esperó'), EST1 = en('estación'), EN2 = en('en', 2), A1924 = en('1924'), PROF = en('profesor'), ADOPTO = en('adoptó'), CACH = en('cachorro'), HACHI1 = en('Hachi');
const MANANA = en('mañana'), ACOMP = en('acompañaba'), EST2 = en('estación', 2), SHIB = en('Shibuya'), Y1 = en('Y'), VOLVIA = en('volvía'), HORA = en('hora'), EXACTA = en('exacta'), LLEGABA = en('llegaba'), TREN = en('tren');
const MAYO = en('mayo'), A1925 = en('1925'), REPENTE = en('repente'), REGRESO = en('regresó'), ESA = en('Esa'), ESPERO2 = en('esperó', 2), EST3 = en('estación', 3), Y2 = en('Y', 2), SIGUIENTE = en('siguiente'), Y3 = en('Y', 3), OTRA = en('otra');
const LO4 = en('Lo', 4), LLEVARON = en('llevaron'), CASAS = en('casas'), ESCAP = en('escapaba'), VOLVER = en('volver'), SHIB2 = en('Shibuya', 2);
const ALGUNOS = en('Algunos'), COMIDA = en('comida'), OTROS = en('Otros'), ECHABAN = en('echaban'), ENTRADA = en('entrada');
const EN7 = en('en', 7), A1932 = en('1932'), PERIOD = en('periódico'), JAPON = en('Japón'), HACHIKO = en('Hachikō');
const EN8 = en('en', 8), A1934 = en('1934'), ESTATUA = en('estatua'), ESTUVO = en('estuvo'), PRESENTE = en('presente');
const SIGUIO = en('Siguió'), A1935 = en('1935'), NUEVE2 = en('Nueve', 2), DIEZ = en('diez'), HOY = en('Hoy'), TOKIO = en('Tokio', 2), QUEDA = en('queda'), VERSE = en('verse'), DICE = en('dice'), VEMOS = en('vemos'), HACHIKO2 = en('Hachikō', 2);
const DALE = en('Dale'), ENVIA = en('envíaselo'), SIEMPRE = en('siempre'), ESPERA = en('espera'), LLEGUES = en('llegues'), TARDE4 = en('tarde', 4);

const LIMA = '#E7FF00';
const CREMA = '#F1E2C6', CREMA_S = '#D2BA90', BLANCO = '#FFF8EA';

const Mundo: React.FC<{children: React.ReactNode; w?: number}> = ({children, w = 4200}) => <svg width={w} height={1920} viewBox={`-600 0 ${w} 1920`} style={{position: 'absolute', left: -600, top: 0, overflow: 'visible'}}>{children}</svg>;

// ---------- piezas dibujadas ----------
// Hachi: akita crema, orejas paradas, cola enroscada, sentado de frente
const Hachi: React.FC<{x: number; y: number; sc?: number; cola?: number; ojos?: number; cachorro?: boolean; viejo?: boolean; bronce?: boolean; cabeza?: number; ang?: number; op?: number; flip?: boolean}> = ({x, y, sc = 1, cola = 1, ojos = 1, cachorro = false, viejo = false, bronce = false, cabeza = 0, ang = 0, op = 1, flip = false}) => {
  const {s} = useS();
  const C = bronce ? {b: '#8C6A3A', d: '#5E4120', w: '#B58E55', n: '#2A1A0A', e: '#6A4C24'} : {b: CREMA, d: CREMA_S, w: BLANCO, n: '#1E1A18', e: '#F2C2B2'};
  const k = cachorro ? 0.62 : 1;
  const hr = cachorro ? 62 : 54;
  const resp = 1 + 0.015 * Math.sin(s * 2.6);
  const wag = cola > 0 ? Math.sin(s * (cola > 1 ? 16 : 5)) * 14 * Math.min(cola, 2) : 0;
  return (
    <g transform={`translate(${x} ${y}) scale(${(flip ? -sc : sc) * resp} ${sc * resp}) rotate(${ang})`} opacity={op}>
      <ellipse cx={0} cy={6} rx={100 * k} ry={14} fill="rgba(0,0,0,0.25)" />
      <g transform={`translate(${64 * k} ${-60 * k}) rotate(${wag})`}>
        <path d="M 0 0 C 80 -10 90 -100 34 -112 C -8 -120 -22 -70 22 -64" stroke={C.b} strokeWidth={34 * k} fill="none" strokeLinecap="round" />
        <path d="M 0 0 C 80 -10 90 -100 34 -112 C -8 -120 -22 -70 22 -64" stroke={C.d} strokeWidth={6} fill="none" strokeLinecap="round" opacity={0.5} />
      </g>
      <ellipse cx={0} cy={-84 * k} rx={72 * k} ry={92 * k} fill={C.b} stroke={C.d} strokeWidth={4} />
      <ellipse cx={0} cy={-76 * k} rx={40 * k} ry={68 * k} fill={C.w} />
      {[-1, 1].map((kk) => (
        <g key={kk}>
          <rect x={kk * 30 * k - 16 * k} y={-72 * k} width={32 * k} height={70 * k} rx={16 * k} fill={C.b} stroke={C.d} strokeWidth={3} />
          <ellipse cx={kk * 30 * k} cy={-2} rx={22 * k} ry={10 * k} fill={C.w} stroke={C.d} strokeWidth={3} />
        </g>
      ))}
      <g transform={`translate(0 ${-186 * k}) rotate(${cabeza})`}>
        <path d="M -40 -34 L -56 -112 L -4 -52 Z" fill={C.b} stroke={C.d} strokeWidth={4} strokeLinejoin="round" />
        <path d="M 40 -34 L 56 -112 L 4 -52 Z" fill={C.b} stroke={C.d} strokeWidth={4} strokeLinejoin="round" />
        <path d="M -38 -50 L -46 -92 L -18 -58 Z" fill={C.e} /><path d="M 38 -50 L 46 -92 L 18 -58 Z" fill={C.e} />
        <circle r={hr} fill={C.b} stroke={C.d} strokeWidth={4} />
        <ellipse cx={0} cy={18} rx={30} ry={24} fill={C.w} />
        {viejo && <ellipse cx={0} cy={20} rx={30} ry={22} fill="rgba(130,130,130,0.35)" />}
        <ellipse cx={0} cy={6} rx={11} ry={8} fill={C.n} />
        <path d="M 0 12 L 0 24 M -14 30 Q 0 40 14 30" stroke={C.n} strokeWidth={4} fill="none" strokeLinecap="round" />
        {[-1, 1].map((kk) => ojos > 0.3
          ? <g key={kk}><ellipse cx={kk * 22} cy={-8} rx={6.5} ry={7 * ojos} fill={C.n} /><circle cx={kk * 22 + 2} cy={-10} r={2.4} fill="#fff" /></g>
          : <path key={kk} d={`M ${kk * 22 - 8} -8 Q ${kk * 22} 0 ${kk * 22 + 8} -8`} stroke={C.n} strokeWidth={4} fill="none" strokeLinecap="round" />)}
      </g>
    </g>
  );
};

// persona genérica para multitudes
const Gente: React.FC<{x: number; y: number; sc?: number; col?: string; fase?: number; dir?: number; vel?: number; op?: number}> = ({x, y, sc = 1, col = '#4A4A5A', fase = 0, dir = 1, vel = 1, op = 1}) => {
  const {s} = useS();
  const sw = Math.sin(s * 8 * vel + fase) * 20;
  return (
    <g transform={`translate(${x} ${y}) scale(${dir * sc} ${sc})`} opacity={op}>
      <rect x={-18} y={-110} width={16} height={110} rx={8} fill={col} transform={`rotate(${sw} -10 -110)`} />
      <rect x={2} y={-110} width={16} height={110} rx={8} fill={col} transform={`rotate(${-sw} 10 -110)`} />
      <rect x={-30} y={-230} width={60} height={130} rx={24} fill={col} />
      <rect x={-44} y={-220} width={14} height={100} rx={7} fill={col} transform={`rotate(${-sw * 0.6} -37 -220)`} />
      <rect x={30} y={-220} width={14} height={100} rx={7} fill={col} transform={`rotate(${sw * 0.6} 37 -220)`} />
      <circle cx={0} cy={-260} r={26} fill="#E3B08A" />
      <path d="M -26 -266 Q 0 -300 26 -266 Q 0 -280 -26 -266 Z" fill="#2A1E16" />
    </g>
  );
};

const Fedora: React.FC<{x: number; y: number; sc?: number; ang?: number}> = ({x, y, sc = 1, ang = 0}) => (
  <g transform={`translate(${x} ${y}) rotate(${ang}) scale(${sc})`}>
    <ellipse cx={0} cy={0} rx={72} ry={16} fill="#2A2420" stroke="#120E0A" strokeWidth={4} />
    <path d="M -40 0 C -44 -50 -26 -62 0 -62 C 26 -62 44 -50 40 0 Z" fill="#3A322C" stroke="#120E0A" strokeWidth={4} />
    <rect x={-40} y={-16} width={80} height={14} fill="#7A4E2D" />
    <ellipse cx={-14} cy={-44} rx={14} ry={7} fill="#fff" opacity={0.15} />
  </g>
);

// profesor Ueno: traje oscuro y sombrero
const Profe: React.FC<{x: number; y: number; sc?: number; sombrero?: boolean; brazo?: number; camina?: number}> = ({x, y, sc = 1, sombrero = true, brazo = 0, camina = 0}) => {
  const {s} = useS();
  const sw = Math.sin(s * 7) * 20 * camina;
  const hx = 50 + 40 * brazo, hy = -170 - 280 * brazo;
  return (
    <g transform={`translate(${x} ${y}) scale(${sc})`}>
      <ellipse cx={0} cy={6} rx={90} ry={12} fill="rgba(0,0,0,0.25)" />
      <rect x={-44} y={-160} width={40} height={160} rx={16} fill="#2C2C38" transform={`rotate(${sw} -24 -160)`} />
      <rect x={4} y={-160} width={40} height={160} rx={16} fill="#2C2C38" transform={`rotate(${-sw} 24 -160)`} />
      <ellipse cx={-26} cy={0} rx={30} ry={10} fill="#14141C" /><ellipse cx={26} cy={0} rx={30} ry={10} fill="#14141C" />
      <rect x={-60} y={-340} width={120} height={200} rx={34} fill="#3A3A4C" stroke="#1E1E2A" strokeWidth={4} />
      <path d="M -12 -336 L 0 -250 L 12 -336 Z" fill="#F4EEE0" /><path d="M 0 -330 L 0 -260" stroke="#8E1E2E" strokeWidth={7} />
      <line x1={-52} y1={-310} x2={-62 + sw * 0.4} y2={-170} stroke="#3A3A4C" strokeWidth={28} strokeLinecap="round" />
      <circle cx={-62 + sw * 0.4} cy={-160} r={14} fill="#E3B08A" />
      <line x1={52} y1={-310} x2={hx} y2={hy} stroke="#3A3A4C" strokeWidth={28} strokeLinecap="round" />
      <circle cx={hx} cy={hy} r={15} fill="#E3B08A" />
      <rect x={-18} y={-362} width={36} height={30} rx={10} fill="#E3B08A" />
      <circle cx={0} cy={-396} r={44} fill="#E3B08A" stroke="#8A6040" strokeWidth={3} />
      <circle cx={-16} cy={-398} r={5} fill="#1E1A18" /><circle cx={16} cy={-398} r={5} fill="#1E1A18" />
      <circle cx={-14} cy={-400} r={1.8} fill="#fff" /><circle cx={18} cy={-400} r={1.8} fill="#fff" />
      <path d="M -14 -376 Q 0 -368 14 -376" stroke="#7A3A2A" strokeWidth={4} fill="none" strokeLinecap="round" />
      <path d="M -22 -382 Q 0 -388 22 -382" stroke="#5A4A3A" strokeWidth={5} fill="none" strokeLinecap="round" opacity={0.8} />
      {sombrero ? <Fedora x={0} y={-430} sc={1.1} /> : <path d="M -40 -420 Q 0 -450 40 -420 Q 0 -432 -40 -420 Z" fill="#6A6A70" />}
    </g>
  );
};

const Fachada: React.FC<{x: number; y: number; w?: number; hh?: number; luz?: number}> = ({x, y, w = 1000, hh = 560, luz = 1}) => (
  <g transform={`translate(${x} ${y})`}>
    <path d={`M -50 0 L ${w / 2} -170 L ${w + 50} 0 Z`} fill="#4A2E1A" stroke="#2A180C" strokeWidth={6} />
    <rect x={0} y={0} width={w} height={hh} fill="#A87440" stroke="#5A3820" strokeWidth={6} />
    {Array.from({length: Math.floor(w / 50)}).map((_, i) => <line key={i} x1={i * 50 + 25} y1={0} x2={i * 50 + 25} y2={hh} stroke="#7A4E2D" strokeWidth={4} opacity={0.65} />)}
    <rect x={w / 2 - 130} y={hh - 350} width={260} height={350} fill="#2A1A0C" />
    <path d={`M ${w / 2 - 130} ${hh - 350} Q ${w / 2} ${hh - 440} ${w / 2 + 130} ${hh - 350} Z`} fill="#2A1A0C" />
    <rect x={w / 2 - 110} y={hh - 330} width={220} height={330} fill="#F6D99A" opacity={0.55 * luz} />
    {[90, w - 230].map((wx) => <g key={wx}><rect x={wx} y={120} width={140} height={160} fill="#F6D99A" opacity={0.4 + 0.5 * luz} stroke="#3A2210" strokeWidth={6} /><line x1={wx + 70} y1={120} x2={wx + 70} y2={280} stroke="#3A2210" strokeWidth={5} /><line x1={wx} y1={200} x2={wx + 140} y2={200} stroke="#3A2210" strokeWidth={5} /></g>)}
    <rect x={w / 2 - 190} y={-40} width={380} height={80} rx={10} fill="#2A1A0C" stroke="#E9B872" strokeWidth={5} />
    <text x={w / 2} y={18} textAnchor="middle" fontFamily="Poppins, Arial, sans-serif" fontWeight={800} fontSize={50} fill="#F6D99A">Shibuya</text>
  </g>
);

const Tren: React.FC<{x: number; y: number; sc?: number}> = ({x, y, sc = 1}) => (
  <g transform={`translate(${x} ${y}) scale(${sc})`}>
    <rect x={-440} y={-310} width={880} height={310} rx={26} fill="#3E5A48" stroke="#1E2E24" strokeWidth={6} />
    <rect x={-440} y={-310} width={880} height={50} rx={22} fill="#2A3F30" />
    {[-360, -230, -100, 100, 230, 300].map((wx) => <rect key={wx} x={wx} y={-230} width={90} height={100} rx={10} fill="#F6D99A" stroke="#1E2E24" strokeWidth={4} />)}
    <rect x={-60} y={-250} width={120} height={250} rx={8} fill="#6A4A2A" stroke="#1E2E24" strokeWidth={4} />
    <rect x={-440} y={-110} width={880} height={14} fill="#C9A23F" />
    <circle cx={-428} cy={-150} r={18} fill="#FFF1B0" /><circle cx={-428} cy={-150} r={40} fill="#FFF1B0" opacity={0.3} />
    {[-340, -200, -60, 60, 200, 340].map((wx) => <circle key={wx} cx={wx} cy={14} r={38} fill="#1E1E20" stroke="#6A6A70" strokeWidth={6} />)}
  </g>
);

// ---------- Sitio 1 y final: estación de Shibuya a la tarde dorada (E1 y E14) ----------
const Estacion: React.FC<{fin?: boolean}> = ({fin = false}) => {
  const {s, lin} = useS();
  const T0 = fin ? DALE - 0.3 : 0;
  const hx = 400;
  const sil = fin ? lin(SIEMPRE - 0.1, SIEMPRE + 0.5, 0, 1) * (1 - lin(TARDE4 - 0.4, TARDE4 + 0.5, 0, 1)) : 0;
  return (
    <AbsoluteFill style={{background: '#EBC07A'}}>
      <Camara paradas={[{t: T0, x: 560, y: 1260, zoom: 1.0}, {t: T0 + 2.6, x: 480, y: 1390, zoom: 1.4}, {t: T0 + 6.5, x: 450, y: 1420, zoom: 1.6}]}>
        <Textura tipo="papel" base="linear-gradient(180deg, #F8DFA6 0%, #EBC07A 45%, #B87A40 100%)" linea="rgba(120,70,30,0.22)" luz="rgba(255,240,200,0.3)" semilla={fin ? 41 : 40} />
        <Brillo x={800} y={520} r={760} color="rgba(255,226,150,0.6)" />
        <Mundo w={2000}>
          <Fachada x={-60} y={480} w={1200} hh={680} />
          <rect x={-600} y={1160} width={2000} height={760} fill="#8A5A34" />
          <rect x={-600} y={1160} width={2000} height={16} fill="#5E3A1E" />
          {Array.from({length: 9}).map((_, i) => <line key={i} x1={-600 + i * 260} y1={1176} x2={-900 + i * 360} y2={1920} stroke="#6E4524" strokeWidth={4} opacity={0.6} />)}
          {[0, 1, 2, 3, 4].map((i) => {
            const sp = (fin ? 120 : 260) + h(i) * 120, dir = i % 2 ? 1 : -1;
            const px = dir > 0 ? ((s * sp + i * 360) % 1800) - 400 : 1500 - ((s * sp + i * 360) % 1800);
            return <Gente key={i} x={px} y={1340} sc={0.95} col={['#4A4A5A', '#6A3A3A', '#3A5A5A', '#5A4A2A', '#4A3A5A'][i]} fase={i} dir={dir} vel={fin ? 0.6 : 1.2} />;
          })}
          {fin ? (
            <>
              <rect x={270} y={1540} width={260} height={110} fill="#8C8F94" stroke="#5E6064" strokeWidth={5} />
              <rect x={250} y={1520} width={300} height={34} fill="#A7AAAF" stroke="#5E6064" strokeWidth={5} />
              <Hachi x={400} y={1530} sc={1.45} bronce cola={0} />
              <Hachi x={720} y={1640} sc={1.45} cola={1} op={sil} />
              <circle cx={720} cy={1440} r={230} fill={LIMA} opacity={0.18 * sil} />
            </>
          ) : (
            <Hachi x={hx} y={1640} sc={1.55} cola={0.4} cabeza={Math.sin(s * 1.6) * 5} />
          )}
          {[0, 1, 2].map((i) => {
            const sp = 330 + h(i + 5) * 120, dir = i % 2 ? 1 : -1;
            const px = dir > 0 ? ((s * sp + i * 600) % 2000) - 500 : 1600 - ((s * sp + i * 600) % 2000);
            return <Gente key={'f' + i} x={px} y={1900} sc={1.5} col={['#2A2A3A', '#5A2A2A', '#2A4A4A'][i]} fase={i * 2} dir={dir} vel={fin ? 0.6 : 1.2} />;
          })}
        </Mundo>
        {!fin && <Ondas x={420} y={1450} t0={EST1} color={LIMA} radio={300} />}
      </Camara>
      {!fin && <Chip texto="0 años" x={300} y={470} t0={0.2} t1={EN2 - 0.2} size={64} />}
    </AbsoluteFill>
  );
};

// ---------- Sitio 2: casa del profesor y calle hasta la estación (E2-E3) ----------
const CASA_RUTA: [number, number][] = [[500, 1610], [1200, 1610], [2000, 1610], [2800, 1610]];
const CASA_CAM: [number, number][] = CASA_RUTA.map(([x]) => [x - 90, 1330] as [number, number]);
const Casa: React.FC = () => {
  const {s, lin, spr} = useS();
  const bajo = lin(ADOPTO + 2.2, MANANA + 0.1, 0, 1, Easing.inOut(Easing.cubic));
  const camina = s > MANANA - 0.2;
  const q = enCamino(s, CASA_RUTA, MANANA - 0.2, SHIB + 0.4);
  const px = camina ? q.x : 500;
  const hx = camina ? q.x - 190 : 624 + (340 - 624) * bajo;
  const hy = camina ? 1670 + Math.abs(Math.sin(s * 9)) * -12 : 990 + (1660 - 990) * bajo;
  const paradas = [{t: EN2, x: 560, y: 940, zoom: 1.9}, {t: HACHI1 + 0.4, x: 540, y: 1140, zoom: 1.0}, ...seguir(CASA_CAM, MANANA - 0.2, SHIB + 0.4, 1.25, 6), {t: SHIB + 0.9, x: 2850, y: 1420, zoom: 1.35}];
  return (
    <AbsoluteFill style={{background: '#E9B872'}}>
      <Camara paradas={paradas}>
        <Mundo w={5000}>
          <defs><linearGradient id="casaCielo" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#F8DFA6" /><stop offset="60%" stopColor="#F0C888" /><stop offset="100%" stopColor="#E0A860" /></linearGradient></defs>
          <rect x={-600} y={0} width={5000} height={1500} fill="url(#casaCielo)" />
          {[1250, 1500, 1800, 2100].map((bx, i) => <g key={bx}><rect x={bx} y={980 - (i % 2) * 120} width={230} height={520 + (i % 2) * 120} fill="#8A5A34" stroke="#4A2E1A" strokeWidth={5} /><path d={`M ${bx - 20} ${980 - (i % 2) * 120} L ${bx + 115} ${860 - (i % 2) * 120} L ${bx + 250} ${980 - (i % 2) * 120} Z`} fill="#3A2412" /><circle cx={bx + 115} cy={1100} r={30} fill="#E8462A" opacity={0.9} /></g>)}
          <rect x={-600} y={1480} width={5000} height={440} fill="#B08A5A" />
          <rect x={-600} y={1480} width={5000} height={12} fill="#7A5A30" />
          <Fachada x={2500} y={900} w={1200} hh={580} />
          <g>
            <rect x={2380} y={1000} width={16} height={480} fill="#3A2412" />
            <rect x={2290} y={1000} width={200} height={70} rx={10} fill="#2A1A0C" stroke="#E9B872" strokeWidth={4} />
            <text x={2390} y={1050} textAnchor="middle" fontFamily="Poppins, Arial, sans-serif" fontWeight={800} fontSize={36} fill="#F6D99A">Shibuya</text>
          </g>
          {/* la casa de madera por dentro */}
          <rect x={-600} y={0} width={1480} height={1920} fill="#C9A06A" />
          {Array.from({length: 30}).map((_, i) => <line key={i} x1={-600 + i * 60} y1={0} x2={-600 + i * 60} y2={1500} stroke="#9A7646" strokeWidth={4} opacity={0.55} />)}
          <rect x={880} y={0} width={220} height={900} fill="#C9A06A" /><rect x={880} y={900} width={30} height={600} fill="#7A4E2D" /><rect x={880} y={880} width={220} height={30} fill="#7A4E2D" />
          <rect x={-600} y={1500} width={1700} height={420} fill="#7A4E2D" />
          {Array.from({length: 12}).map((_, i) => <line key={i} x1={-600} y1={1520 + i * 36} x2={1100} y2={1520 + i * 36} stroke="#5A3820" strokeWidth={4} opacity={0.5} />)}
          <rect x={150} y={420} width={420} height={420} fill="#FFE9B0" opacity={0.85} stroke="#7A4E2D" strokeWidth={10} />
          {[0, 1, 2].map((i) => <line key={'a' + i} x1={150 + 140 * (i + 1) - 140 * (i === 2 ? 1 : 0)} y1={420} x2={150 + 140 * (i + 1) - 140 * (i === 2 ? 1 : 0)} y2={840} stroke="#7A4E2D" strokeWidth={6} />)}
          {[0, 1, 2].map((i) => <line key={'b' + i} x1={150} y1={560 + 140 * i} x2={570} y2={560 + 140 * i} stroke="#7A4E2D" strokeWidth={6} />)}
          <path d="M 150 840 L 570 840 L 760 1500 L -40 1500 Z" fill="#FFE9B0" opacity={0.18} />
          <rect x={-20} y={1380} width={380} height={30} fill="#5A3820" /><rect x={20} y={1410} width={20} height={90} fill="#5A3820" /><rect x={300} y={1410} width={20} height={90} fill="#5A3820" />
          <g opacity={s > MANANA - 0.5 ? 0 : 1}><Profe x={px} y={1610} sc={1.55} brazo={1 - bajo} camina={0} /></g>
          {s > MANANA - 0.5 && <Profe x={px} y={1610} sc={1.55} brazo={0} camina={camina ? 1 : 0} />}
          <Hachi x={hx} y={hy} sc={camina ? 0.95 : 0.9} cachorro cola={2} />
        </Mundo>
